// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }

    function testFuzz_property(address depositor, uint256 amount) public {
        vm.assume(depositor != address(0));
        amount = bound(amount, 1, 1 ether);

        vm.deal(depositor, amount);

        vm.prank(depositor);
        (bool sent,) = address(c).call{value: amount}("");
        require(sent);

        bool ok;
        vm.prank(depositor);
        try c.withdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(c.balances(depositor) == 0);
        } else {
            assertTrue(false);
        }
    }
}
